import React, {
  useEffect,
  useCallback,
  useContext,
  useMemo,
  useState,
} from "react";
import { Row, Col, Select } from "antd";
import { usePremiumHooksList } from "../../state/hooks/usePremiumHooks";
// import FileEditor from "./FileEditor";
import { store } from "../../store";
import { get } from 'lodash'

const { Option } = Select;
function PredefinedFunctionPremium({
  sectionView,
  initialFormData = {},
  parentKey,
}) {
  const [{ getPremiumHooksData = {} }, getPremiumHooksRequest] =
    usePremiumHooksList();
  const { state, dispatch } = useContext(store);
  const initAttributePath =
    parentKey ||
    (sectionView === "endorsement"
      ? "endorsement_new_premium_logic.premium_logic"
      : "new_premium_logic.premium_logic");
  const fieldKey = parentKey || initAttributePath;
  const fieldValuePath = `${fieldKey}.value`;
  const inputValue = get(state, fieldValuePath, '')
  const handleHookChange = (e) => {
    dispatch({
      type: "update-store",
      payload: {
        view: sectionView,
        key: fieldValuePath,
        data:e,
      }
    });
  };

  useEffect(() => {
    fetch();
  }, []);

  const hooksList = useMemo(() => {
    if (getPremiumHooksData.success) {
      return getPremiumHooksData?.data?.details;
    }
  }, [getPremiumHooksData]);

  const fetch = useCallback(() => {
    getPremiumHooksRequest();
  }, [getPremiumHooksRequest]);

  return (
    <>
      <Row>
        <Col
          xs={{
            span: 6,
            // offset: 1,
          }}
          lg={{
            span: 3,
            // offset: 2,
          }}
        >
          <p className="additional-info">
            <b>Select Function:</b>
          </p>
        </Col>
        <Col
          xs={{
            span: 5,
            offset: 1,
          }}
          lg={{
            span: 6,
            offset: 1,
          }}
        >
          <Select value={inputValue} onChange={handleHookChange}>
            {hooksList?.map((item) => (
              <Option key={item?.id} value={item?.code}>
                {item?.code}
              </Option>
              
            ))}
              {/* <Option key={1} value="b2c_mapped_occupation_type">
                b2c_mapped_occupation_type
              </Option>
              <Option key={2} value="test">
                test
              </Option>
              <Option key={3} value="test2">
                test2
              </Option>
              <Option key={4} value="test3">
                test3
              </Option> */}
          </Select>
        </Col>
      </Row>
      {/* <Row>
        <Col>
          <FileEditor  
            parentKey={parentKey}
            sectionView={sectionView}
            initialFormData={initialFormData}
           />
        </Col>
      </Row> */}
    </>
  );
}

export default PredefinedFunctionPremium;
