import useServiceRequest from "../../../../../../../../../../../hooks/useServiceRequest";
import actions from "../actions";
import { usePremiumHooksContextValue } from '../../context';

export const usePremiumHooksServiceCall = (actionsCall = () => { }) => {
    const [hooksState, dispatch] = usePremiumHooksContextValue()
    const [callApi] = useServiceRequest(dispatch)
    const request = async (payload = {}) => {
        await callApi(
            actionsCall({
              ...payload
            })
          )
    }
    return [hooksState, request]
  }
  
  export const usePremiumHooksList = () => {
    return usePremiumHooksServiceCall(actions.getPremiumHooks)
  }
