import { FixedComponent } from '../normalPremium/FixedComponent'
import { DerivedComponent } from '../normalPremium/DerivedComponent'
import { MapBasedComponent } from '../normalPremium/mapBasedComponent'
import { RangeBasedComponent } from '../normalPremium/rangeBasedComponent'
import { AgeBasedComponent } from '../normalPremium/AgeBasedComponent'

export function getFormItems (formData) {
  // TODO: Figure out why this and PremiumTypeComponent cannot be made into single component
  const {
    type,
    sectionView,
    parentKey,
    initialFormData,
    attributesData
  } = formData

  switch (type) {
    case 'fixed':
      return (
        <FixedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
        />
      )
    case 'derived':
      return (
        <DerivedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    case 'mapped':
      return (
        <MapBasedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    case 'ranged': {
      return (
        <RangeBasedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    }
    case 'age': {
      return (
        <AgeBasedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    }
    case 'nested': {
      return (
        <div>
          Nested
        </div>
      )
    }
    default:
      return (
        <div>
          Unconfigured type: {type}
        </div>
      )
  }
}
