import { getHeader } from "../../../../../../../../../../helpers/utility";
import fileUrls from "../../../../../../../../../../request/urls/file";
import productConfigUrls from "../../../../../../../../../../request/urls/productConfig";

const actions = {
    GET_PREMIUM_HOOKS_REQUEST:'GET_PREMIUM_HOOKS_REQUEST',
    GET_PREMIUM_HOOKS_SUCCESS:'GET_PREMIUM_HOOKS_SUCCESS',
    GET_PREMIUM_HOOKS_FAILURE:'GET_PREMIUM_HOOKS_FAILURE',
    GET_PREMIUM_HOOKS : 'GET_PREMIUM_HOOKS',
    UPLOAD_FILE_BY_SIGNED_URL_REQUEST: 'UPLOAD_FILE_BY_SIGNED_URL_REQUEST',
    UPLOAD_FILE_BY_SIGNED_URL_FAILURE: 'UPLOAD_FILE_BY_SIGNED_URL_FAILURE',
    UPLOAD_FILE_BY_SIGNED_URL_SUCCESS: 'UPLOAD_FILE_BY_SIGNED_URL_SUCCESS',
    getPremiumHooks: (payload) => {
        return {
          type: actions.GET_PREMIUM_HOOKS_REQUEST,
          payload: {
            ...payload,
            method: 'authGet',
            url: productConfigUrls.getPremiumHooksUrl,
            headers: getHeader()
          }
        }
      },
      getFileploadData: payload => {
      return{
        type: actions.UPLOAD_FILE_BY_SIGNED_URL_REQUEST,
        payload: {
          ...payload,
          method: 'authPost',
          url: fileUrls.getPremiumHooksUrl,
          headers: getHeader()
        }
      }
    },
}

export default actions