import { useContext } from 'react'
import { store } from '../../../store'
import { get } from 'lodash'
import { MapDerived } from './MapDerivedTable'
import { AgeDerived } from './AgeDerivedTable'
import { RangedDerived } from './RangedDerived'
import { AgeRangedMapped } from './AgeRangeMappedTable'
import { RangeMappedTable } from './RangeMappedTable'
import TableStyleWrapper from './tableWrapperStyle.style'

export default function TableSection ({ type, fieldKey, initRootAttributePath, sectionView }) {
  const { state } = useContext(store)
  switch (type) {
    case 'endorsement_mapped_derived':
    case 'mapped_derived': {
      const initialData = get(state, fieldKey, [{}])
      return (
        <TableStyleWrapper>
          <MapDerived
            fieldKey={fieldKey}
            initRootAttributePath={initRootAttributePath}
            sectionView={sectionView}
            initialData={initialData}
          />
        </TableStyleWrapper>
      )
    }
    case 'endorsement_age_derived':
    case 'age_derived': {
      const initialData = get(state, fieldKey, {})
      return (
        <TableStyleWrapper>
          <AgeDerived
            sectionView={sectionView}
            initialData={initialData}
            fieldKey={fieldKey}
            initRootAttributePath={initRootAttributePath}
          />
        </TableStyleWrapper>
      )
    }
    case 'endorsement_ranged_derived':
    case 'ranged_derived': {
      const initialData = get(state, fieldKey, [{}])
      return (
        <TableStyleWrapper>
          <RangedDerived
            sectionView={sectionView}
            initialData={initialData}
            fieldKey={fieldKey}
            initRootAttributePath={initRootAttributePath}
          />
        </TableStyleWrapper>
      )
    }
    case 'endorsement_age_mapped':
    case 'age_mapped': {
      const initialData = get(state, fieldKey, {})
      return (
        <TableStyleWrapper>
          <AgeRangedMapped
            type='age'
            sectionView={sectionView}
            tableValue={type}
            initialData={initialData}
            fieldKey={fieldKey}
            initRootAttributePath={initRootAttributePath}
          />
        </TableStyleWrapper>
      )
    }
    case 'endorsement_ranged_mapped':
    case 'ranged_mapped': {
      const initialData = get(state, fieldKey, [{}])
      return (
        <TableStyleWrapper>
          <RangeMappedTable
            type='ranged'
            sectionView={sectionView}
            tableValue={type}
            initialData={initialData}
            fieldKey={fieldKey}
            initRootAttributePath={initRootAttributePath}
          />
        </TableStyleWrapper>
      )
    }
    default: return ''
  }
}
