/* eslint-disable react-hooks/exhaustive-deps */
import { Select, InputNumber, Input, Icon } from 'antd'
import React, { useContext, useEffect } from 'react'
import { store } from '../../../../store'
import TableStyledContainer from './index.style'
import { get } from 'lodash'
const { Option } = Select

export function AgeRangedMapped ({ initialData = {}, type, fieldKey, initRootAttributePath, sectionView }) {
  const { state, dispatch } = useContext(store)
  // const firstProductAttributeId = get(state, `${initRootAttributePath}.${type}.product_attribute_id`, get(state, `${fieldKey}[0].product_attribute_id`))
  const mappedProductAttributeId = get(state, `${initRootAttributePath}.mapped.product_attribute_id`, get(state, `${fieldKey}.values[0].value.premium_logic[0].product_attribute_id`))
  const ageTableData = get(initialData, 'values', [{}])
  const firstParameterData = get(state, `${initRootAttributePath}.${type}.first_parameter`)
  const secondParameterData = get(state, `${initRootAttributePath}.${type}.second_parameter`)
  const unitParameterData = get(state, `${initRootAttributePath}.${type}.unit`, '')

  useEffect(() => {
    if (firstParameterData) {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}.first_parameter`,
          data: firstParameterData
        }
      })
    }
  }, [firstParameterData])

  useEffect(() => {
    if (secondParameterData) {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}.second_parameter`,
          data: secondParameterData
        }
      })
    }
  }, [secondParameterData])

  useEffect(() => {
    if (unitParameterData) {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}.unit`,
          data: unitParameterData
        }
      })
    }
  }, [unitParameterData])

  useEffect(() => {
    const updatedData = ageTableData.map(data => {
      let childData = {}
      if (data?.value?.premium_logic) {
        childData = data?.value?.premium_logic

        if (!Array.isArray(childData)) {
          // TODO: Change this
          childData = [childData]
        }

        childData = childData.map(childData => ({
          ...childData,
          product_attribute_id: mappedProductAttributeId
        }))
      }
      return {
        ...data,
        value: {
          ...data.value,
          premium_logic: childData
        }
      }
    })

    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values`,
        data: updatedData
      }
    })
  }, [mappedProductAttributeId])

  // useEffect(() => {
  //   const updatedData = ageTableData.map(data => {
  //     let childData = [{}]
  //     if (data?.value?.premium_logic) {
  //       childData = data?.value?.premium_logic.map(childData => ({
  //         ...childData,
  //         product_attribute_id: mappedProductAttributeId
  //       }))
  //     }

  //     return {
  //       ...data,
  //       value: {
  //         ...data?.value,
  //         premium_logic: childData
  //       }
  //     }
  //   })

  //   dispatch({
  //     type: 'update-store',
  //     payload: {
  //       view: sectionView,
  //       key: `${fieldKey}.values`,
  //       data: updatedData
  //     }
  //   })
  // }, [mappedProductAttributeId])

  const onChangeHandler = (e, type, fieldType, id) => {
    // let payload = []
    // dispatch({
    //   type: 'update-store',
    //   payload: {
    //     view: sectionView,
    //     key: `${fieldKey}.values[${id}].product_attribute_id`,
    //     data: firstProductAttributeId
    //   }
    // })
    switch (type) {
      case 'low': {
        if (fieldType === 'select') {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}.values[${id}].lower_operator`,
              data: e
            }
          })
        } else {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}.values[${id}].lower_operand`,
              data: e
            }
          })
        }
        break
      }
      case 'high': {
        if (fieldType === 'select') {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}.values[${id}].upper_operator`,
              data: e
            }
          })
        } else {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}.values[${id}].upper_operand`,
              data: e
            }
          })
        }
        break
      }
      default: return ''
    }
  }
  const premiumHandler = (e, fieldType, childId, parentId) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values[${parentId}].value.premium_type`,
        data: 'mapped'
      }
    })
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values[${parentId}].value.premium_logic[${childId}].product_attribute_id`,
        data: mappedProductAttributeId
      }
    })
    switch (fieldType) {
      case 'operand': {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${fieldKey}.values[${parentId}].value.premium_logic[${childId}].operand`,
            data: e.target.value
          }
        })
        break
      }
      case 'value':
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${fieldKey}.values[${parentId}].value.premium_logic[${childId}].value`,
            data: e
          }
        })
        break
      default: return {}
    }
  }

  const addButtonHandler = () => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values`,
        data: [...initialData, {
          product_attribute_id: mappedProductAttributeId
        }]
      }
    })
  }

  const deleteButtonHandler = (id) => {
    const filterData = get(state, `${fieldKey}.values`).filter((_item, index) => index !== id)
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values`,
        data: filterData
      }
    })
  }

  const addButtonHandlerChild = (_childIndex, parentId) => {
    const childValues = get(state, `${fieldKey}.values[${parentId}].value.premium_logic`, [{}])
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values[${parentId}].value.premium_logic`,
        data: [...childValues, {}]
      }
    })
  }

  const deleteButtonHandlerChild = (childIndex, parentId) => {
    const filterData = get(state, `${fieldKey}.values[${parentId}].value.premium_logic`).filter((_item, index) => index !== childIndex)
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values[${parentId}].value.premium_logic`,
        data: filterData
      }
    })
  }

  return (
    <TableStyledContainer>
      <table style={{ tableLayout: 'fixed' }}>
        <thead>
          <tr>
            <th>{type === 'age' ? 'Age' : 'Range'} Lower Value</th>
            <th>{type === 'age' ? 'Age' : 'Range'} Higher Value</th>
            <th className='premium-section'>Premium</th>
            <th className='action-section' />
          </tr>
        </thead>
        <tbody>
          {
            ageTableData.map((item, parentIndex) => {
              let mappedTableData = get(item, 'value.premium_logic', [{}])
              if (!Array.isArray(mappedTableData)) {
                // TODO: Change this
                mappedTableData = [mappedTableData]
              }
              return (
                <tr key={parentIndex}>
                  <td>
                    <div className='row-flex'>
                      <Select value={item.lower_operator} onChange={(e) => onChangeHandler(e, 'low', 'select', parentIndex)}>
                        <Option value='gt'>gt</Option>
                        <Option value='gte'>gte</Option>
                      </Select>&nbsp;
                      <InputNumber value={item.lower_operand} onChange={(e) => onChangeHandler(e, 'low', 'input', parentIndex)} />
                    </div>
                  </td>
                  <td>
                    <div className='row-flex'>
                      <Select value={item.upper_operator} onChange={(e) => onChangeHandler(e, 'high', 'select', parentIndex)}>
                        <Option value='lt'>lt</Option>
                        <Option value='lte'>lte</Option>
                      </Select>&nbsp;
                      <InputNumber value={item.upper_operand} onChange={(e) => onChangeHandler(e, 'high', 'input', parentIndex)} />
                    </div>
                  </td>
                  <td>
                    <table>
                      <thead>
                        <tr>
                          <th>Map Value</th>
                          <th>Premium</th>
                          <th />
                        </tr>
                      </thead>
                      <tbody>
                        {
                          mappedTableData && mappedTableData.map((element, childIndex) => {
                            return (
                              <tr key={childIndex}>
                                <td>
                                  <Input
                                    className='mapped-derived'
                                    value={element.operand}
                                    onChange={(e) => premiumHandler(e, 'operand', childIndex, parentIndex)}
                                  />
                                </td>
                                <td>
                                  <InputNumber
                                    required
                                    className='full-width mapped-derived'
                                    formatter={value => `${value}%`}
                                    value={element.value}
                                    onChange={(e) => premiumHandler(e, 'value', childIndex, parentIndex)}
                                  />
                                </td>
                                <td>
                                  <div className='iconDiv'>
                                    <Icon
                                      className='dynamic-add-button button-size'
                                      type='plus-circle'
                                      theme='filled'
                                      onClick={() => addButtonHandlerChild('', parentIndex)}
                                    />
                                    {
                                      mappedTableData.length > 1 &&
                                        <Icon
                                          className='dynamic-delete-button button-size'
                                          type='minus-circle'
                                          theme='filled'
                                          onClick={() => deleteButtonHandlerChild(childIndex, parentIndex)}
                                        />
                                    }
                                  </div>
                                </td>
                              </tr>
                            )
                          })
                        }
                      </tbody>
                    </table>
                  </td>

                  <td>
                    <div className='iconDiv'>
                      <Icon
                        className='dynamic-add-button button-size'
                        type='plus-circle'
                        theme='filled'
                        onClick={() => addButtonHandler(initialData)}
                      />
                      {
                        ageTableData.length > 1 &&
                          <Icon
                            className='dynamic-delete-button button-size'
                            type='minus-circle'
                            theme='filled'
                            onClick={() => deleteButtonHandler(parentIndex)}
                          />
                      }
                    </div>
                  </td>
                </tr>
              )
            })
          }
        </tbody>
      </table>
    </TableStyledContainer>
  )
}
