import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducer'

export const PremiumHooksContext = createContext()

export const PremiumHooksProvider = (props) => {
  return (
    <PremiumHooksContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </PremiumHooksContext.Provider>
  )
}

export const usePremiumHooksContextValue = () => useContext(PremiumHooksContext)
