import { useContext, useState } from 'react'
import { NestedPremiumContainer } from './index.style'
import { store } from '../../store'
import { get, size } from 'lodash'
import { Select, Icon, Input } from 'antd'
import FormItems from './FormItems'
import RangeType from './RangeType'
import EndItem from './EndItem'
import CalculationForm from './CalculationForm'

const { Option } = Select

export default function NestedPremium ({ attributesData, initialFormData = {}, sectionView, parentKey, getFieldDecorator }) {
  const { state, dispatch } = useContext(store)
  const [inputDisable, setInputDisable] = useState([])
  const initAttributePath = sectionView === 'endorsement' ? 'endorsement_new_premium_logic.premium_logic' : 'new_premium_logic.premium_logic'

  const fieldKey = parentKey || initAttributePath
  const fieldObj = get(state, fieldKey, {})

  const isDuration = get(fieldObj, 'premium_type') === 'age'
  const valuePath = isDuration ? 'premium_logic.values' : 'premium_logic'

  const fieldLogicValue = get(state, `${fieldKey}.${valuePath}`, [])

  const add = () => {
    const nextNumber = fieldLogicValue.length
    setInputDisable(oldArray => [...oldArray, true])
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.${valuePath}[${nextNumber}]`,
        data: {}
      }
    })
  }

  const remove = k => {
    const currArr = [...fieldLogicValue]
    currArr.splice(k, 1)
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.${valuePath}`,
        data: currArr
      }
    })
  }

  const handleChangeNestType = (e) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.premium_type`,
        data: e
      }
    })
    if (e === 'age') {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}.premium_logic`,
          data: {}
        }
      })
    }
  }

  const handleEyeBtn = (idx) => {
    const currArr = [...inputDisable]
    currArr[idx] = !currArr[idx]
    setInputDisable(currArr)
  }

  const handleChildTypeChange = (value, idx) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.${valuePath}[${idx}].value.premium_type`,
        data: value
      }
    })
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.${valuePath}[${idx}].value.premium_logic`,
        data: null
      }
    })
  }

  const handleEndTypeChange = (value, path) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: path,
        data: value
      }
    })
  }

  return (
    <NestedPremiumContainer>
      <section className='nested-premium__item-list'>
        <span className='nested-premium__title'>
          1st Calculation
        </span>
        <Select style={{ width: 200 }} value={get(state, `${fieldKey}.premium_type`)} onChange={e => handleChangeNestType(e)}>
          <Option key='mapped' value='mapped'>Mapped</Option>
          <Option key='ranged' value='ranged'>Ranged Based</Option>
          <Option key='age' value='age'>Duration Based</Option>
        </Select>
        <CalculationForm
          fieldKey={fieldKey}
          parentKey={`${fieldKey}.premium_logic`}
          type={get(fieldObj, 'premium_type')}
          attributesData={attributesData}
          initialFormData={initialFormData}
          required
        />
        {fieldLogicValue && Array.isArray(fieldLogicValue) && fieldLogicValue.map((_, idx) => {
          const endPremiumType = get(state, `${fieldKey}.${valuePath}[${idx}].value.premium_type`)
          const endIsDuration = endPremiumType === 'age'
          const endValuePath = endIsDuration ? 'premium_logic.values' : 'premium_logic'
          const endItems = get(state, `${fieldKey}.${valuePath}[${idx}].value.${endValuePath}`, [])
          return (
            <div key={idx} className='nested-premium__item'>
              <section className='nested-premium__map-item'>
                <RangeType
                  parentKey={`${fieldKey}.${valuePath}[${idx}]`}
                  type={get(state, `${fieldKey}.premium_type`)}
                  attributesData={attributesData}
                  initialFormData={initialFormData}
                  sectionView={sectionView}
                  required
                />
              </section>
              <section>
                {/* TODO: move to component */}
                <div className='nested-premium__mid-item-container'>
                  <Select
                    style={{ width: 200 }}
                    value={get(state, `${fieldKey}.${valuePath}[${idx}].value.premium_type`)}
                    // onChange={e => handleChildTypeChange(e, `${fieldKey}.${valuePath}[${idx}].value.premium_type`)}
                    onChange={e => handleChildTypeChange(e, idx)}
                  >
                    <Option key='fixed' value='fixed'>Fixed</Option>
                    <Option key='derived' value='derived'>Derived</Option>
                    <Option key='mapped' value='mapped'>Mapped</Option>
                    <Option key='ranged' value='ranged'>Ranged Based</Option>
                    <Option key='age' value='age'>Duration Based</Option>
                  </Select>
                  <div>
                    {
                      get(state, `${fieldKey}.${valuePath}[${idx}].value.premium_type`) && (
                        <FormItems
                          parentKey={`${fieldKey}.${valuePath}[${idx}].value.premium_logic`}
                          type={get(state, `${fieldKey}.${valuePath}[${idx}].value.premium_type`)}
                          attributesData={attributesData}
                          initialFormData={initialFormData}
                          sectionView={sectionView}
                          required
                        />
                      )
                    }
                  </div>
                </div>
              </section>
              {
                (Array.isArray(endItems) && size(endItems) > 0) && (
                  <section
                    className={`nested-premium__end-item-container nested-premium__end-item-container--${get(state, `${fieldKey}.${valuePath}[${idx}].value.premium_type`)}`}
                  >
                    {
                      endItems.map((_, endItemIndex) => {
                        return (
                          <div
                            key={endItemIndex}
                            className='nested-premium__end-item-child'
                          >
                            <Select
                              style={{ width: 200 }}
                              value={get(state, `${fieldKey}.${valuePath}[${idx}].value.${endValuePath}.${endItemIndex}].value.premium_type`)}
                              onChange={e => handleEndTypeChange(e, `${fieldKey}.${valuePath}[${idx}].value.${endValuePath}.${endItemIndex}].value.premium_type`)}
                            >
                              <Option key='fixed' value='fixed'>Fixed</Option>
                              <Option key='derived' value='derived'>Derived</Option>
                            </Select>
                            <div className='nested-premium__end-item-value'>
                              <EndItem
                                parentKey={`${fieldKey}.${valuePath}[${idx}].value.${endValuePath}.${endItemIndex}].value.premium_logic`}
                                type={get(state, `${fieldKey}.${valuePath}[${idx}].value.${endValuePath}.${endItemIndex}].value.premium_type`)}
                                attributesData={attributesData}
                                initialFormData={initialFormData}
                                sectionView={sectionView}
                                required
                              />
                            </div>
                          </div>
                        )
                      })
                    }
                  </section>
                )
              }
              {
                <div>
                  <label>Tag</label><br />
                  <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                    {
                      getFieldDecorator(`${fieldKey}.${valuePath}[${idx}].premium_logic.code`, {
                        rules: [
                          {
                            required: true,
                            message: 'required'
                          }
                        ],
                        initialValue: get(state, `${fieldKey}.${valuePath}[${idx}].premium_logic.code`) || get(state, `${fieldKey}.${valuePath}[${idx}].value.premium_type`)
                      })(<Input style={{ width: '200px' }} disabled={inputDisable[idx]} className='tag-input' />)
                    }
                    <Icon type='eye' className='pointer' onClick={() => handleEyeBtn(idx)} />
                  </div>

                </div>
              }
              {
                fieldLogicValue.length > 1
                  ? (
                    <Icon
                      className='dynamic-delete-button'
                      type='minus-circle-o'
                      onClick={() => remove(idx)}
                    />
                    )
                  : null
                }
            </div>
          )
        })}
      </section>
      <Icon
        className='nested__row-add dynamic-add-button button-size'
        type='plus-circle'
        theme='filled'
        onClick={add}
      />
    </NestedPremiumContainer>
  )
}
