import { useContext } from 'react'
import { Row, Col, TreeSelect } from 'antd'
import { childNode } from '../../../../../../../../components/formItem'
import { MappedTableComponent } from './mappedTable'
import { get } from 'lodash'
import { store } from '../../store'

export const MapBasedComponent = ({ sectionView, initialFormData = {}, attributesData, parentKey }) => {
  const { state, dispatch } = useContext(store)
  const initAttributePath = parentKey || (sectionView === 'endorsement' ? 'endorsement_new_premium_logic.premium_logic' : 'new_premium_logic.premium_logic')
  const fieldKey = parentKey || initAttributePath
  const values = get(state, fieldKey, [])
  const productAttributeId = get(values, '[0].product_attribute_id')

  const onChangeHandler = (value) => {
    if (values.length) {
      const dataMap = values.map(item => ({ ...item, product_attribute_id: value }))
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: fieldKey,
          data: dataMap
        }
      })
    } else {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: fieldKey,
          data: [{
            operand: '',
            value: '',
            showAddButton: true,
            showDeleteButton: false,
            product_attribute_id: value
          }]
        }
      })
    }
  }

  return (
    <>
      <Row type='flex'>
        <Col span={20}>
          <Row type='flex' gutter={20}>
            <Col>
              <p><b>Policy data as parameter</b></p>
            </Col>
            <Col>
              <TreeSelect
                parentKey={parentKey}
                value={productAttributeId}
                placeholder='Select Attribute...'
                treeDefaultExpandAll
                onChange={onChangeHandler}
              >
                {childNode(attributesData)}
              </TreeSelect>
            </Col>
          </Row>
        </Col>
        {productAttributeId &&
          <MappedTableComponent
            parentKey={parentKey}
            fieldKey={fieldKey}
            initialFormData={initialFormData}
            productAttributeId={productAttributeId}
            sectionView={sectionView}
          />}
      </Row>
    </>
  )
}
