import { useContext } from 'react'
import { Col, Icon, Input, InputNumber } from 'antd'
import { get } from 'lodash'
import { store } from '../../store'

export const MappedTableComponent = ({ sectionView, parentKey, initialFormData, fieldKey, productAttributeId }) => {
  const { state, dispatch } = useContext(store)
  const tableData = get(state, fieldKey)

  const inputHandler = (e, id, fieldName) => {
    // TODO: Find a better solution
    if (productAttributeId) {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}[${id}].product_attribute_id`,
          data: productAttributeId
        }
      })
    }

    switch (fieldName) {
      case 'operand':
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${fieldKey}[${id}].operand`,
            data: e.target.value
          }
        })
        break
      case 'premium':
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${fieldKey}[${id}].value`,
            data: e
          }
        })
        break
      default: return null
    }
  }

  const addButtonHandler = () => {
    const localDerivedData = [...tableData, {
      operand: '',
      value: '',
      showAddButton: true,
      showDeleteButton: false,
      product_attribute_id: productAttributeId
    }]

    dispatchRegular(localDerivedData)
  }

  const deleteButtonHandler = (deletionIdx) => {
    let localDerivedData = [...tableData]
    localDerivedData = localDerivedData.filter((item, itemIdx) => itemIdx !== deletionIdx)

    dispatchRegular(localDerivedData)
  }

  const dispatchRegular = (value) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: value
      }
    })
  }

  return (
    <Col className='margin40' span={20}>
      <table>
        <thead>
          <tr>
            <th>
              Value
            </th>
            <th>
              Premium
            </th>
            <th />
          </tr>
        </thead>
        <tbody>
          {
            tableData.map((item, itemIdx) => {
              return (
                <tr key={itemIdx}>
                  <td>
                    <Input className='mappedInput' value={item.operand} onChange={(e) => inputHandler(e, itemIdx, 'operand')} />
                  </td>
                  <td>
                    <InputNumber
                      required
                      className='mappedInput'
                      value={item.value}
                      onChange={(e) => inputHandler(e, itemIdx, 'premium')}
                    />
                  </td>
                  <td>
                    <div className='iconDiv'>
                      <Icon
                        className='dynamic-add-button button-size'
                        type='plus-circle'
                        theme='filled'
                        onClick={addButtonHandler}
                      />
                      {
                        tableData.length > 1 &&
                          <Icon
                            className='dynamic-delete-button button-size'
                            type='minus-circle'
                            theme='filled'
                            onClick={() => deleteButtonHandler(itemIdx)}
                          />
                      }
                    </div>
                  </td>
                </tr>
              )
            })
          }
        </tbody>
      </table>
    </Col>
  )
}
