import React from 'react'
import { FixedComponent } from './components/normalPremium/FixedComponent'
import { DerivedComponent } from './components/normalPremium/DerivedComponent'
import { MapBasedComponent } from './components/normalPremium/mapBasedComponent'
import { RangeBasedComponent } from './components/normalPremium/rangeBasedComponent'
import { AgeBasedComponent } from './components/normalPremium/AgeBasedComponent'
import CombinedPremium from './components/combinedPremium'
import MultipliedPremium from './components/MultipliedPremium'
import SummationPremium from './components/SummationPremium'
import NestedPremium from './components/NestedPremium'
import PredefinedPremium from './components/PredefinedFunctionPremium'

export default function PremiumTypeComponent (props) {
  // TODO: Figure out why this and getFormItems cannot be made into single component
  const {
    type,
    sectionView,
    initialFormData,
    attributesData,
    parentKey,
    getFieldDecorator
  } = props

  switch (type) {
    case 'fixed': {
      return (
        <FixedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
        />
      )
    }
    case 'derived': {
      return (
        <DerivedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    }
    case 'mapped': {
      return (
        <MapBasedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    }
    case 'ranged': {
      return (
        <RangeBasedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    }
    case 'age': {
      return (
        <AgeBasedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    }
    case 'combined': {
      return (
        <CombinedPremium
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    }
    case 'multiplied': {
      return (
        <MultipliedPremium
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
          getFieldDecorator={getFieldDecorator}
        />
      )
    }
    case 'summation': {
      return (
        <SummationPremium
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
          getFieldDecorator={getFieldDecorator}
        />
      )
    }
    case 'nested': {
      return (
        <NestedPremium
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
          getFieldDecorator={getFieldDecorator}
        />
      )
    }
    case 'hook':{
      return (
        <PredefinedPremium
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
          getFieldDecorator={getFieldDecorator}
        />
      )
    }
    default:
      return (
        <div>
          Unconfigured type {type}
        </div>
      )
  }
}
