import { FixedComponent } from '../normalPremium/FixedComponent'
import { DerivedComponent } from '../normalPremium/DerivedComponent'

// import { store } from '../../store'

export default function EndItem (formData) {
  // TODO: Figure out why this and PremiumTypeComponent cannot be made into single component
  const {
    type,
    sectionView,
    parentKey,
    initialFormData,
    attributesData
  } = formData

  switch (type) {
    case 'fixed':
      return (
        <FixedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
        />
      )
    case 'derived':
      return (
        <DerivedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    default:
      return (
        <div>
          Unconfigured type: {type}
        </div>
      )
  }
}
