import { useContext, useState } from 'react'
import { MultipliedPremiumContainer } from './index.style'
import { store } from '../../store'
import { get } from 'lodash'
import { Select, Icon, Input } from 'antd'
import { getFormItems } from './getFormItems'

const { Option } = Select

export default function MultipliedPremium ({ attributesData, initialFormData = {}, sectionView, parentKey, getFieldDecorator }) {
  const { state, dispatch } = useContext(store)
  const initAttributePath = sectionView === 'endorsement' ? 'endorsement_new_premium_logic.premium_logic' : 'new_premium_logic.premium_logic'
  const fieldKey = parentKey || initAttributePath
  const [inputDisable, setInputDisable] = useState([])

  const values = get(state, fieldKey, [])
  const add = () => {
    const nextNumber = values.length
    setInputDisable(oldArray => [...oldArray, true])
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}[${nextNumber}]`,
        data: {}
      }
    })
  }

  const remove = k => {
    const currArr = [...values]
    currArr.splice(k, 1)

    const curInput = [...inputDisable]
    curInput.splice(k, 1)

    dispatchInit(currArr)
    setInputDisable(curInput)
  }

  const dispatchInit = (value) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: value
      }
    })
  }

  const handleChangeAttributeType = (e, idx) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}[${idx}].premium_type`,
        data: e
      }
    })
  }

  const handleEyeBtn = (idx) => {
    const currArr = [...inputDisable]
    currArr[idx] = !currArr[idx]
    setInputDisable(currArr)
  }

  return (
    <MultipliedPremiumContainer>
      <p>This logic will multiply the result of each premium logic added below</p>
      <section className='multiplied-premium__item-list'>
        {values.map((_, idx) => (
          <div key={idx} className='multiplied-premium__item'>
            <div className='multiplied-tag__wrapper'>
              <Select
                style={{ width: 200 }}
                value={get(values, `[${idx}].premium_type`)}
                onChange={e => handleChangeAttributeType(e, idx)}
              >
                <Option key='fixed' value='fixed'>Fixed</Option>
                <Option key='derived' value='derived'>Derived</Option>
                <Option key='mapped' value='mapped'>Mapped</Option>
                <Option key='ranged' value='ranged'>Ranged Based</Option>
                <Option key='age' value='age'>Duration Based</Option>
              </Select>
              <div className='tag-wrapper'>
                <label>Tag Name {'  '}</label>
                {
                  getFieldDecorator(`${fieldKey}[${idx}].premium_logic.code`, {
                    rules: [
                      {
                        required: true,
                        message: 'required'
                      }
                    ],
                    initialValue: get(values, `[${idx}].premium_logic.code`) || get(values, `[${idx}].premium_type`)
                  })(<Input disabled={inputDisable[idx]} className='tag-input' />)
                }
                <Icon type='eye' className='pointer' onClick={() => handleEyeBtn(idx)} />
              </div>
            </div>

            <div className='multiplied__field'>
              {
                getFormItems.call(this, {
                  parentKey: `${fieldKey}[${idx}].premium_logic`,
                  type: get(values, `[${idx}].premium_type`),
                  required: true,
                  attributesData,
                  initialFormData,
                  sectionView
                })
              }
            </div>
            {
              values.length > 1
                ? (
                  <Icon
                    className='dynamic-delete-button'
                    type='minus-circle-o'
                    onClick={() => remove(idx)}
                  />
                  )
                : null
              }
          </div>
        ))}
      </section>
      <Icon
        className='multiplied__row-add dynamic-add-button button-size'
        type='plus-circle'
        theme='filled'
        onClick={add}
      />
    </MultipliedPremiumContainer>
  )
}
