import { useContext } from 'react'
import { Row, Col, Input } from 'antd'
import { get } from 'lodash'
import { store } from '../../store'

export const FixedComponent = ({ sectionView, initialFormData = {}, parentKey }) => {
  const { state, dispatch } = useContext(store)
  const initAttributePath = parentKey || (sectionView === 'endorsement' ? 'endorsement_new_premium_logic.premium_logic' : 'new_premium_logic.premium_logic')
  const fieldKey = parentKey || initAttributePath

  const fieldValuePath = `${fieldKey}.value`
  const inputValue = get(state, fieldValuePath, '')

  const dispatchUpdate = (value) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldValuePath,
        data: Number(value)
      }
    })
  }

  const updateHandler = (e) => {
    dispatchUpdate(e.target.value)
  }

  return (
    <>
      <Row type='flex' gutter={20} align='middle'>
        <Col>
          <p className='text-between'><b>Fixed amount: </b></p>
        </Col>
        <Col>
          <Input type='number' required className='fixedInput' min={0} step={0.0000000001} value={inputValue} onChange={updateHandler} />
        </Col>
      </Row>
    </>
  )
}
