import { useContext } from 'react'
import { Row, Col, TreeSelect, Select } from 'antd'
import { get, size } from 'lodash'
import { childNode } from '../../../../../../../../components/formItem'
// import AttributesType from './attributeTypes'
import AttributeStyleContainer from './attributeSelection.style'

import { store } from '../../store'

const { Option } = Select

export default function AttributeSection ({
  type,
  fieldKey,
  initRootAttributePath,
  // premiumType1,
  // premiumType2,
  attributesData,
  sectionView
}) {
  const { state, dispatch } = useContext(store)
  switch (type) {
    case 'endorsement_mapped_derived':
    case 'mapped_derived': {
      const initialMappedValue = get(state, `${fieldKey}[0].product_attribute_id`)
      const mappedValue = get(state, `${initRootAttributePath}.mapped.product_attribute_id`, initialMappedValue)
      const initialDerivedValue = get(state, `${fieldKey}[0].value.premium_logic.product_attribute_id`)
      const derivedValue = get(state, `${initRootAttributePath}.derived.product_attribute_id`, initialDerivedValue)

      const onChangeMap = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.mapped.product_attribute_id`,
            data: e
          }
        })
      }
      const onChangeDerived = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.derived.product_attribute_id`,
            data: e
          }
        })
      }
      return (
        <>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Map Based Config</b></p>
            <Row type='flex' gutter={100}>
              <Col>
                <p>Policy data as parameter</p>
              </Col>
              <Col>
                <TreeSelect
                  value={mappedValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeMap(e)}
                >
                  {
                    childNode(attributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
          </AttributeStyleContainer>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Percentage Based Config</b></p>
            <Row type='flex' gutter={100}>
              <Col>
                <p>Policy data as parameter</p>
              </Col>
              <Col>
                <TreeSelect
                  value={derivedValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeDerived(e)}
                >
                  {
                    childNode(attributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
          </AttributeStyleContainer>
        </>
      )
    }
    case 'endorsement_age_mapped':
    case 'age_mapped' : {
      const initialMappedValue = get(state, `${fieldKey}.values[0].value.premium_logic[0].product_attribute_id`)
      const mappedValue = get(state, `${initRootAttributePath}.mapped.product_attribute_id`, initialMappedValue)

      const localAttributesData = attributesData
      const intialAttributesData = localAttributesData.find(item => item.id === 'currentTime') || {}
      if (size(intialAttributesData) === 0) {
        localAttributesData.unshift({
          attribute_type: '',
          id: 'currentTime',
          name: 'Current Time',
          nested: []
        })
      }
      const firstParameter = get(state, `${initRootAttributePath}.age.first_parameter`, get(state, `${fieldKey}.first_parameter`, {}))
      const secondParameter = get(state, `${initRootAttributePath}.age.second_parameter`, get(state, `${fieldKey}.second_parameter`, {}))
      const unitValue = get(state, `${initRootAttributePath}.age.unit`, get(state, `${fieldKey}.unit`, ''))

      const firstParameterValue = firstParameter.is_current_time ? 'currentTime' : firstParameter.product_attribute_id
      const secondParameterValue = secondParameter.is_current_time ? 'currentTime' : secondParameter.product_attribute_id

      const onChangeFirstParameter = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.age.first_parameter`,
            data: {
              is_current_time: e === 'currentTime',
              product_attribute_id: e === 'currentTime' ? null : e
            }
          }
        })
      }

      const onChangeSecondParameter = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.age.second_parameter`,
            data: {
              is_current_time: e === 'currentTime',
              product_attribute_id: e === 'currentTime' ? null : e
            }
          }
        })
      }

      const onChangeUnit = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.age.unit`,
            data: e
          }
        })
      }

      const onChangeMapped = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.mapped.product_attribute_id`,
            data: e
          }
        })
      }

      return (
        <>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Age Based Config</b></p>
            <Row type='flex' gutter={50}>
              <Col>
                <span> Age =</span>
              </Col>
              <Col>
                <TreeSelect
                  value={firstParameterValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeFirstParameter(e)}
                >
                  {
                    childNode(localAttributesData)
                  }
                </TreeSelect>&nbsp; -
              </Col>
              <Col>
                <TreeSelect
                  value={secondParameterValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeSecondParameter(e)}
                >
                  {
                    childNode(localAttributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
            <Row type='flex' gutter={20}>
              <Col>
                <p>Calculate Unit = </p>
              </Col>
              <Col>
                <Select
                  value={unitValue}
                  onChange={(e) => onChangeUnit(e)}
                >
                  <Option value='year'>Year</Option>
                  <Option value='month'>Month</Option>
                  <Option value='day'>Day</Option>
                </Select>
              </Col>
            </Row>
          </AttributeStyleContainer>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Map Based Config</b></p>
            <Row type='flex' gutter={100}>
              <Col>
                <p>Policy data as parameter</p>
              </Col>
              <Col>
                <TreeSelect
                  value={mappedValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeMapped(e)}
                >
                  {
                    childNode(attributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
          </AttributeStyleContainer>
        </>
      )
    }
    case 'endorsement_age_derived':
    case 'age_derived': {
      const initialMappedValue = get(state, `${fieldKey}.values[0].value.premium_logic.product_attribute_id`)
      const derivedValue = get(state, `${initRootAttributePath}.derived.product_attribute_id`, initialMappedValue)

      const localAttributesData = attributesData
      const intialAttributesData = localAttributesData.find(item => item.id === 'currentTime') || {}
      if (size(intialAttributesData) === 0) {
        localAttributesData.unshift({
          attribute_type: '',
          id: 'currentTime',
          name: 'Current Time',
          nested: []
        })
      }
      const firstParameter = get(state, `${initRootAttributePath}.age.first_parameter`, get(state, `${fieldKey}.first_parameter`, {}))
      const secondParameter = get(state, `${initRootAttributePath}.age.second_parameter`, get(state, `${fieldKey}.second_parameter`, {}))
      const unitValue = get(state, `${initRootAttributePath}.age.unit`, get(state, `${fieldKey}.unit`, ''))

      const firstParameterValue = firstParameter.is_current_time ? 'currentTime' : firstParameter.product_attribute_id
      const secondParameterValue = secondParameter.is_current_time ? 'currentTime' : secondParameter.product_attribute_id

      const onChangeFirstParameter = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.age.first_parameter`,
            data: {
              is_current_time: e === 'currentTime',
              product_attribute_id: e === 'currentTime' ? null : e
            }
          }
        })
      }

      const onChangeSecondParameter = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.age.second_parameter`,
            data: {
              is_current_time: e === 'currentTime',
              product_attribute_id: e === 'currentTime' ? null : e
            }
          }
        })
      }

      const onChangeUnit = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.age.unit`,
            data: e
          }
        })
      }

      const onChangeDerived = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.derived.product_attribute_id`,
            data: e
          }
        })
      }

      return (
        <>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Age Based Config</b></p>
            <Row type='flex' gutter={50}>
              <Col>
                <span> Age =</span>
              </Col>
              <Col>
                <TreeSelect
                  value={firstParameterValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeFirstParameter(e)}
                >
                  {
                    childNode(localAttributesData)
                  }
                </TreeSelect>&nbsp; -
              </Col>
              <Col>
                <TreeSelect
                  value={secondParameterValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeSecondParameter(e)}
                >
                  {
                    childNode(localAttributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
            <Row type='flex' gutter={20}>
              <Col>
                <p>Calculate Unit = </p>
              </Col>
              <Col>
                <Select
                  value={unitValue}
                  onChange={(e) => onChangeUnit(e)}
                >
                  <Option value='year'>Year</Option>
                  <Option value='month'>Month</Option>
                  <Option value='day'>Day</Option>
                </Select>
              </Col>
            </Row>
          </AttributeStyleContainer>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Percentage Based Config</b></p>
            <Row type='flex' gutter={100}>
              <Col>
                <p>Policy data as parameter</p>
              </Col>
              <Col>
                <TreeSelect
                  value={derivedValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeDerived(e)}
                >
                  {
                    childNode(attributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
          </AttributeStyleContainer>
        </>
      )
    }
    case 'endorsement_ranged_mapped':
    case 'ranged_mapped': {
      const initialRangedValue = get(state, `${fieldKey}[0].product_attribute_id`)
      const rangedValue = get(state, `${initRootAttributePath}.ranged.product_attribute_id`, initialRangedValue)
      const initialMappedValue = get(state, `${fieldKey}[0].value.premium_logic[0].product_attribute_id`)
      const mappedValue = get(state, `${initRootAttributePath}.mapped.product_attribute_id`, initialMappedValue)

      const onChangeRanged = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.ranged.product_attribute_id`,
            data: e
          }
        })
      }

      const onChangeMapped = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.mapped.product_attribute_id`,
            data: e
          }
        })
      }

      return (
        <>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Ranged Based Config</b></p>
            <Row type='flex' gutter={100}>
              <Col>
                <p>Policy data as parameter</p>
              </Col>
              <Col>
                <TreeSelect
                  value={rangedValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeRanged(e)}
                >
                  {
                    childNode(attributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
          </AttributeStyleContainer>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Map Based Config</b></p>
            <Row type='flex' gutter={100}>
              <Col>
                <p>Policy data as parameter</p>
              </Col>
              <Col>
                <TreeSelect
                  value={mappedValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeMapped(e)}
                >
                  {
                    childNode(attributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
          </AttributeStyleContainer>
        </>
      )
    }
    case 'endorsement_ranged_derived':
    case 'ranged_derived': {
      const initialRangedValue = get(state, `${fieldKey}[0].product_attribute_id`)
      const rangedValue = get(state, `${initRootAttributePath}.ranged.product_attribute_id`, initialRangedValue)
      const initialDerivedValue = get(state, `${fieldKey}[0].value.premium_logic.product_attribute_id`)
      const derivedValue = get(state, `${initRootAttributePath}.derived.product_attribute_id`, initialDerivedValue)

      const onChangeRanged = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.ranged.product_attribute_id`,
            data: e
          }
        })
      }
      const onChangeDerived = (e) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${initRootAttributePath}.derived.product_attribute_id`,
            data: e
          }
        })
      }
      return (
        <>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Map Based Config</b></p>
            <Row type='flex' gutter={100}>
              <Col>
                <p>Policy data as parameter</p>
              </Col>
              <Col>
                <TreeSelect
                  value={rangedValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeRanged(e)}
                >
                  {
                    childNode(attributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
          </AttributeStyleContainer>
          <AttributeStyleContainer>
            <p className='section-heading'><b>Percentage Based Config</b></p>
            <Row type='flex' gutter={100}>
              <Col>
                <p>Policy data as parameter</p>
              </Col>
              <Col>
                <TreeSelect
                  value={derivedValue}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={(e) => onChangeDerived(e)}
                >
                  {
                    childNode(attributesData)
                  }
                </TreeSelect>
              </Col>
            </Row>
          </AttributeStyleContainer>
        </>
      )
    }
    default:
      return 'Not Configured'
  }
}
