import { useContext } from 'react'
import { Row, Col, InputNumber, TreeSelect } from 'antd'
import { childNode } from '../../../../../../../../components/formItem'
import { get } from 'lodash'
import { store } from '../../store'

export const DerivedComponent = ({ sectionView, initialFormData = {}, attributesData, parentKey }) => {
  const { state, dispatch } = useContext(store)
  const initAttributePath = parentKey || (sectionView === 'endorsement' ? 'endorsement_new_premium_logic.premium_logic' : 'new_premium_logic.premium_logic')
  const fieldKey = parentKey || initAttributePath
  // const { value: inputValue, product_attribute_id: treeInputValue } = get(state, fieldKey, {})
  const fieldObj = get(state, fieldKey, {})

  const inputHandler = (value) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.value`,
        data: value
      }
    })
  }

  const selectHandler = (value) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.product_attribute_id`,
        data: value
      }
    })
  }

  return (
    <>
      <Row type='flex' gutter={20} align='middle'>
        <Col>
          <p><b>Premium Derived</b></p>
        </Col>
        <Col>
          <Row type='flex' gutter={20}>
            <Col>
              <InputNumber className='fixedInput' value={get(fieldObj, 'value')} onChange={inputHandler} />
            </Col>
            <Col>
              <p className='text-between'>% of</p>
            </Col>
            <Col>
              <TreeSelect
                value={get(fieldObj, 'product_attribute_id')}
                placeholder='Select Attribute...'
                treeDefaultExpandAll
                onChange={selectHandler}
              >
                {childNode(attributesData)}
              </TreeSelect>
            </Col>
          </Row>
        </Col>
      </Row>
    </>
  )
}
