/* eslint-disable react-hooks/exhaustive-deps */
import { useContext, useEffect } from 'react'
import { Input, Icon, InputNumber } from 'antd'
import { get } from 'lodash'
import { store } from '../../../../store'

export function MapDerived ({ initialData, fieldKey, initRootAttributePath, sectionView }) {
  const { state, dispatch } = useContext(store)
  const mappedProductAttributeId = get(state, `${initRootAttributePath}.mapped.product_attribute_id`, get(state, `${fieldKey}[0].product_attribute_id`))
  const derivedProductAttributeId = get(state, `${initRootAttributePath}.derived.product_attribute_id`, get(state, `${fieldKey}[0].value.premium_logic.product_attribute_id`))

  useEffect(() => {
    const updatedData = initialData.map(data => ({
      ...data,
      product_attribute_id: mappedProductAttributeId
    }))

    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: updatedData
      }
    })
  }, [mappedProductAttributeId])

  useEffect(() => {
    const updatedData = initialData.map(data => ({
      ...data,
      value: {
        ...data?.value,
        premium_logic: {
          ...data?.value?.premium_logic,
          product_attribute_id: derivedProductAttributeId
        }
      }
    }))

    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: updatedData
      }
    })
  }, [derivedProductAttributeId])

  const handleChange = (e, type, key) => {
    if (type === 'mapped') {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}[${key}].operand`,
          data: e.target.value
        }
      })
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}[${key}].product_attribute_id`,
          data: mappedProductAttributeId
        }
      })
    } else {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}[${key}].value`,
          data: {
            premium_logic: {
              value: Number(e),
              product_attribute_id: derivedProductAttributeId
            },
            premium_type: 'derived'
          }
        }
      })
    }
  }

  const addButtonHandler = () => {
    const updatedData = [...initialData, {
      showAddButton: true,
      showDeleteButton: true,
      value: {
        premium_logic: {},
        premium_type: 'derived'
      },
      operand: null,
      product_attribute_id: mappedProductAttributeId
    }]

    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: updatedData
      }
    })
  }

  const deleteButtonHandler = (id) => {
    const filterData = get(state, `${fieldKey}`).filter((item, index) => index !== id)
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: filterData
      }
    })
  }
  return (
    <table>
      <thead>
        <tr>
          <th>Map Value</th>
          <th>Derived Value</th>
          <th />
        </tr>
      </thead>
      <tbody>
        {
          initialData.map((item, index) => {
            return (
              <tr key={index}>
                <td>
                  <Input
                    className='mapped-derived'
                    value={get(item, 'operand', '')}
                    onChange={(e) => handleChange(e, 'mapped', index)}
                  />
                </td>
                <td>
                  <InputNumber
                    required
                    className='full-width mapped-derived'
                    value={get(item, 'value.value', get(item, 'value.premium_logic.value', ''))}
                    formatter={value => `${value}%`}
                    parser={value => value.replace('%', '')}
                    onChange={(e) => handleChange(e, 'derived', index)}
                  />
                </td>
                <td>
                  <div className='iconDiv'>
                    <Icon
                      className='dynamic-add-button button-size'
                      type='plus-circle'
                      theme='filled'
                      onClick={() => addButtonHandler()}
                    />
                    {
                      initialData.length > 1 &&
                        <Icon
                          className='dynamic-delete-button button-size'
                          type='minus-circle'
                          theme='filled'
                          onClick={() => deleteButtonHandler(index)}
                        />
                    }
                  </div>
                </td>
              </tr>
            )
          })
        }
      </tbody>
    </table>
  )
}
