import axios from 'axios'

export const axiosInterceptorRequest = (getObj = () => {}) => {
  // obj is the key-value pair that need to send request to server
  axios.interceptors.request.use((config) => {
    const obj = getObj()
    if (obj) {
      config.params = {
        ...config.params,
        ...obj
      }
      return config
    }
    return config
  }, (error) => {
    return Promise.reject(error)
  })
}

const axiosInterceptor = {
  axiosInterceptorRequest
}

export default axiosInterceptor
