import { useContext } from 'react'
import { Col, InputNumber, Icon, Select } from 'antd'
import { get } from 'lodash'
import { store } from '../../store'
import { DEFAULT_AGE_ROW_DATA } from '../../constants'

const { Option } = Select

export const RangeBasedTable = ({ sectionView, parentKey, productAttributeId }) => {
  const { state, dispatch } = useContext(store)
  const tableData = get(state, parentKey, DEFAULT_AGE_ROW_DATA)

  const hightValue = [{ code: 'gt', name: 'gt' }, { code: 'gte', name: 'gte' }]
  const lowValue = [{ code: 'lt', name: 'lt' }, { code: 'lte', name: 'lte' }]

  const inputHandler = (e, field, id, fieldName) => {
    // TODO: Find a better solution
    if (productAttributeId) {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${parentKey}[${id}].product_attribute_id`,
          data: productAttributeId
        }
      })
    }

    switch (fieldName) {
      case 'low':
        if (field === 'select') {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${parentKey}[${id}].lower_operator`,
              data: e
            }
          })
        } else {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${parentKey}[${id}].lower_operand`,
              data: e
            }
          })
        }
        break
      case 'high':
        if (field === 'select') {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${parentKey}[${id}].upper_operator`,
              data: e
            }
          })
        } else {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${parentKey}[${id}].upper_operand`,
              data: e
            }
          })
        }
        break
      case 'premium':
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}[${id}].value`,
            data: e
          }
        })
        break
      default: return null
    }
  }

  const addButtonHandler = () => {
    const localDerivedData = [...tableData, {
      lower_operator: '',
      lower_operand: '',
      upper_operator: '',
      upper_operand: '',
      value: '',
      product_attribute_id: productAttributeId
    }]
    dispatchRegular(localDerivedData)
  }

  const deleteButtonHandler = (deletionIdx) => {
    let localDerivedData = [...tableData]
    localDerivedData = localDerivedData.filter((item, itemIdx) => itemIdx !== deletionIdx)

    dispatchRegular(localDerivedData)
  }

  const dispatchRegular = (value) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${parentKey}`,
        data: value
      }
    })
  }

  return (
    <Col className='margin40' span={24}>
      <table className='rangedTable'>
        <thead>
          <tr>
            <th>
              Low Value
            </th>
            <th>
              High Value
            </th>
            <th>
              Premium
            </th>
            <th />
          </tr>
        </thead>
        <tbody>
          {
            tableData.map((item, itemIdx) => {
              return (
                <tr key={itemIdx}>
                  <td>
                    <div className='rangedField'>
                      <Select
                        className='selectRanged'
                        defaultValue={item.lower_operator}
                        onChange={(e) => inputHandler(e, 'select', itemIdx, 'low')}
                      >
                        {
                          hightValue.map((item, index) => <Option key={index} value={item.code}>{item.name}</Option>)
                        }
                      </Select>
                      <InputNumber
                        className='selectInput'
                        value={item.lower_operand}
                        onChange={(e) => inputHandler(e, 'input', itemIdx, 'low')}
                      />
                    </div>
                  </td>
                  <td>
                    <div className='rangedField'>
                      <Select
                        className='selectRanged'
                        defaultValue={item.upper_operator}
                        onChange={(e) => inputHandler(e, 'select', itemIdx, 'high')}
                      >
                        {
                          lowValue.map((item, index) => <Option key={index} value={item.code}>{item.name}</Option>)
                        }
                      </Select>
                      <InputNumber
                        className='selectInput'
                        value={item.upper_operand}
                        onChange={(e) => inputHandler(e, 'input', itemIdx, 'high')}
                      />
                    </div>
                  </td>
                  <td className='premiumTd'>
                    <InputNumber
                      className='mappedInput rangedInput'
                      value={item.value}
                      onChange={(e) => inputHandler(e, 'input', itemIdx, 'premium')}
                    />
                  </td>
                  <td>
                    <div className='iconDiv'>
                      <Icon
                        className='dynamic-add-button button-size'
                        type='plus-circle'
                        theme='filled'
                        onClick={addButtonHandler}
                      />
                      {
                        tableData.length > 1 &&
                          <Icon
                            className='dynamic-delete-button button-size'
                            type='minus-circle'
                            theme='filled'
                            onClick={() => deleteButtonHandler(itemIdx)}
                          />
                      }
                    </div>
                  </td>
                </tr>
              )
            })
          }
        </tbody>
      </table>
    </Col>
  )
}
