import { useContext, useEffect, useState } from 'react'
import { Row, Col, TreeSelect, Select } from 'antd'
import { childNode } from '../../../../../../../../components/formItem'
import { RangeBasedTable } from './rangedTable'
import { get } from 'lodash'
import { store } from '../../store'

const { Option } = Select
export const AgeBasedComponent = ({
  sectionView,
  attributesData,
  parentKey
}) => {
  const [localAttributesData, setLocalAttributesData] = useState(attributesData)
  const { state, dispatch } = useContext(store)
  const initAttributePath = parentKey || (sectionView === 'endorsement' ? 'endorsement_new_premium_logic.premium_logic' : 'new_premium_logic.premium_logic')
  const fieldKey = parentKey || initAttributePath
  const fieldObj = get(state, fieldKey, {})
  const { first_parameter: firstParameter, second_parameter: secondParameter, unit: selectUnit, values = [] } = fieldObj
  const treeSelectInput1 = get(firstParameter, 'is_current_time', false) ? 'currentTime' : get(firstParameter, 'product_attribute_id')
  const treeSelectInput2 = get(secondParameter, 'is_current_time', false) ? 'currentTime' : get(secondParameter, 'product_attribute_id')

  useEffect(() => {
    if (!attributesData.find(x => x.id === 'currentTime')) {
      setLocalAttributesData([{
        attribute_type: '',
        id: 'currentTime',
        name: 'Current Time',
        nested: []
      }, ...attributesData])
    }
  }, [attributesData])

  const updateHandler = (e, type) => {
    switch (type) {
      case 1:
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${fieldKey}.first_parameter`,
            data: {
              is_current_time: e === 'currentTime',
              product_attribute_id: e !== 'currentTime' ? e : null
            }
          }
        })
        break
      case 2:
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${fieldKey}.second_parameter`,
            data: {
              is_current_time: e === 'currentTime',
              product_attribute_id: e !== 'currentTime' ? e : null
            }
          }
        })
        if (values.length === 0) {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}.values`,
              data: [{}]
            }
          })
        }
        break
      case 3:
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${fieldKey}.unit`,
            data: e
          }
        })
        break
      default: return null
    }
  }
  return (
    <>
      <Row type='flex'>
        <Col span={20}>
          <Row type='flex' gutter={20} align='top'>
            <Col>
              <p>Age = </p>
            </Col>
            <Col>
              <TreeSelect
                value={treeSelectInput1}
                placeholder='Select Attribute...'
                treeDefaultExpandAll
                onChange={(e) => updateHandler(e, 1)}
              >
                {
                  childNode(localAttributesData)
                }
              </TreeSelect>
            </Col>
            <Col><span> - </span></Col>
            <Col>
              <TreeSelect
                value={treeSelectInput2}
                placeholder='Select Attribute...'
                treeDefaultExpandAll
                onChange={(e) => updateHandler(e, 2)}
              >
                {
                  childNode(localAttributesData)
                }
              </TreeSelect>
            </Col>
          </Row>
          <Row className='margin40' type='flex' gutter={20}>
            <Col>
              <p>Calculation unit</p>
            </Col>
            <Col>
              <Select value={selectUnit} onChange={(e) => updateHandler(e, 3)}>
                <Option value='year'>Year</Option>
                <Option value='month'>Month</Option>
                <Option value='day'>Day</Option>
              </Select>
            </Col>
          </Row>
        </Col>
        {
          (treeSelectInput1 && treeSelectInput2) &&
            <RangeBasedTable
              type='age'
              parentKey={`${fieldKey}.values`}
              sectionView={sectionView}
              // fieldKey={fieldKey}
            />
        }
      </Row>
    </>
  )
}
