import { useContext } from 'react'
import { Input } from 'antd'
import { get } from 'lodash'
import styled from 'styled-components'

import { store } from '../../store'

const DurationWrapper = styled.div`
  .duration-item {
    display: flex;
  }
  .duration-addon {
    padding: 5px;
    border-right: 1px solid black;
    transition: all 0.2s ease-out;

    &:last-child {
      border-right: unset;
    }
    &--active {
      background-color: #1890ff;
      color: #fff;
    }
  }

  .duration-addon-container {
    display: flex;
    border: 1px solid black;
    border-radius: 4px;
  }
`

const RangedWrapper = styled.div`
  .ranged-item {
    display: flex;
  }
  .ranged-addon {
    padding: 5px;
    border-right: 1px solid black;
    transition: all 0.2s ease-out;

    &:last-child {
      border-right: unset;
    }
    &--active {
      background-color: #1890ff;
      color: #fff;
    }
  }

  .ranged-addon-container {
    display: flex;
    border: 1px solid black;
    border-radius: 4px;
  }
`

export default function RangeType (props) {
  // TODO: Figure out why this and PremiumTypeComponent cannot be made into single component
  const {
    type,
    sectionView,
    parentKey
    // initialFormData,
    // attributesData
  } = props

  const { state, dispatch } = useContext(store)

  switch (type) {
    case 'mapped': {
      const onChangeHandler = (e) => {
        const values = get(state, parentKey, {})
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: parentKey,
            data: { ...values, operand: e.target.value }
          }
        })
      }

      return (
        <div>
          <span>Map Value</span>
          <Input style={{ width: '100%' }} value={get(state, `${parentKey}.operand`)} onChange={onChangeHandler} />
        </div>
      )
    }
    case 'age': {
      const onChangeHandler = (value, path) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: path,
            data: value
          }
        })
      }

      const currUpperValue = get(state, `${parentKey}.upper_operator`)
      const currLowerValue = get(state, `${parentKey}.lower_operator`)
      return (
        <DurationWrapper>
          <span>Duration Value</span>
          <div className='duration-item'>
            <div className='duration-addon-container'>
              <div
                className={'duration-addon' + (currUpperValue === 'gt' ? ' duration-addon--active' : '')}
                onClick={() => onChangeHandler('gt', `${parentKey}.upper_operator`)}
              >
                gt
              </div>
              <div
                className={'duration-addon' + (currUpperValue === 'gte' ? ' duration-addon--active' : '')}
                onClick={() => onChangeHandler('gte', `${parentKey}.upper_operator`)}
              >
                gte
              </div>
            </div>
            <Input
              type='number'
              style={{ width: '100%' }}
              value={get(state, `${parentKey}.upper_operand`)}
              onChange={e => onChangeHandler(Number(e?.target?.value), `${parentKey}.upper_operand`)}
            />
          </div>
          <div>
            <div className='duration-item'>
              <div className='duration-addon-container'>
                <div
                  className={'duration-addon' + (currLowerValue === 'lt' ? ' duration-addon--active' : '')}
                  onClick={() => onChangeHandler('lt', `${parentKey}.lower_operator`)}
                >
                  lt
                </div>
                <div
                  className={'duration-addon' + (currLowerValue === 'lte' ? ' duration-addon--active' : '')}
                  onClick={() => onChangeHandler('lte', `${parentKey}.lower_operator`)}
                >
                  lte
                </div>
              </div>
              <Input
                type='number'
                style={{ width: '100%' }}
                value={get(state, `${parentKey}.lower_operand`)}
                onChange={e => onChangeHandler(Number(e?.target?.value), `${parentKey}.lower_operand`)}
              />
            </div>
          </div>
        </DurationWrapper>
      )
    }
    case 'ranged': {
      const onChangeHandler = (value, path) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: path,
            data: value
          }
        })
      }

      const currUpperValue = get(state, `${parentKey}.upper_operator`)
      const currLowerValue = get(state, `${parentKey}.lower_operator`)
      return (
        <RangedWrapper>
          <span>Range Value</span>
          <div className='ranged-item'>
            <div className='ranged-addon-container'>
              <div
                className={'ranged-addon' + (currUpperValue === 'gt' ? ' ranged-addon--active' : '')}
                onClick={() => onChangeHandler('gt', `${parentKey}.upper_operator`)}
              >
                gt
              </div>
              <div
                className={'ranged-addon' + (currUpperValue === 'gte' ? ' ranged-addon--active' : '')}
                onClick={() => onChangeHandler('gte', `${parentKey}.upper_operator`)}
              >
                gte
              </div>
            </div>
            <Input
              style={{ width: '100%' }}
              type='number'
              value={get(state, `${parentKey}.upper_operand`)}
              onChange={e => onChangeHandler(Number(e?.target?.value), `${parentKey}.upper_operand`)}
            />
          </div>
          <div>
            <div className='ranged-item'>
              <div className='ranged-addon-container'>
                <div
                  className={'ranged-addon' + (currLowerValue === 'lt' ? ' ranged-addon--active' : '')}
                  onClick={() => onChangeHandler('lt', `${parentKey}.lower_operator`)}
                >
                  lt
                </div>
                <div
                  className={'ranged-addon' + (currLowerValue === 'lte' ? ' ranged-addon--active' : '')}
                  onClick={() => onChangeHandler('lte', `${parentKey}.lower_operator`)}
                >
                  lte
                </div>
              </div>
              <Input
                style={{ width: '100%' }}
                type='number'
                value={get(state, `${parentKey}.lower_operand`)}
                onChange={e => onChangeHandler(Number(e?.target?.value), `${parentKey}.lower_operand`)}
              />
            </div>
          </div>
        </RangedWrapper>
      )
    }
    default:
      return (
        <div>
          Unconfigured type: {type}
        </div>
      )
  }
}
