/* eslint-disable react-hooks/exhaustive-deps */
import { Select, InputNumber, Icon } from 'antd'
import { useContext, useEffect } from 'react'
import { get } from 'lodash'
import { store } from '../../../../store'
// import { buttonHandlerFunction } from './helperFunction'
const { Option } = Select

export function AgeDerived ({ initialData = {}, type, fieldKey, initRootAttributePath, sectionView }) {
  const { state, dispatch } = useContext(store)
  const derivedProductAttributeId = get(state, `${initRootAttributePath}.derived.product_attribute_id`, get(state, `${fieldKey}.values[0].value.premium_logic.product_attribute_id`))

  const ageTableData = get(initialData, 'values', [{}])
  const firstParameterData = get(state, `${initRootAttributePath}.age.first_parameter`)
  const secondParameterData = get(state, `${initRootAttributePath}.age.second_parameter`)
  const unitParameterData = get(state, `${initRootAttributePath}.age.unit`, '')

  useEffect(() => {
    if (firstParameterData) {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}.first_parameter`,
          data: firstParameterData
        }
      })
    }
  }, [firstParameterData])

  useEffect(() => {
    if (secondParameterData) {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}.second_parameter`,
          data: secondParameterData
        }
      })
    }
  }, [secondParameterData])

  useEffect(() => {
    if (unitParameterData) {
      dispatch({
        type: 'update-store',
        payload: {
          view: sectionView,
          key: `${fieldKey}.unit`,
          data: unitParameterData
        }
      })
    }
  }, [unitParameterData])

  useEffect(() => {
    const updatedData = ageTableData.map(data => {
      let childData = {}
      if (data?.value?.premium_logic) {
        childData = {
          ...data?.value?.premium_logic,
          product_attribute_id: derivedProductAttributeId
        }
      }
      return {
        ...data,
        value: {
          ...data.value,
          premium_logic: childData
        }
      }
    })

    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values`,
        data: updatedData
      }
    })
  }, [derivedProductAttributeId])

  const onChangeHandler = (e, type, fieldType, id) => {
    switch (type) {
      case 'low': {
        if (fieldType === 'select') {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}.values[${id}].lower_operator`,
              data: e
            }
          })
        } else {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}.values[${id}].lower_operand`,
              data: Number(e)
            }
          })
        }
        break
      }
      case 'high': {
        if (fieldType === 'select') {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}.values[${id}].upper_operator`,
              data: e
            }
          })
        } else {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}.values[${id}].upper_operand`,
              data: Number(e)
            }
          })
        }
        break
      }
      default: return ''
    }
  }

  const derivedPercentageHandler = (e, id) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values[${id}].value`,
        data: {
          premium_logic: {
            value: e,
            product_attribute_id: derivedProductAttributeId
          },
          premium_type: 'derived'
        }
      }
    })
  }

  const addButtonHandler = () => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values`,
        data: [...ageTableData, {
          product_attribute_id: derivedProductAttributeId
        }]
      }
    })
  }

  const deleteButtonHandler = (id) => {
    const filterData = get(state, `${fieldKey}.values`).filter((_item, index) => index !== id)
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}.values`,
        data: filterData
      }
    })
  }

  return (
    <table>
      <thead>
        <tr>
          <th>Age Lower Value</th>
          <th>Age Higher Value</th>
          <th>Premium</th>
          <th />
        </tr>
      </thead>
      <tbody>
        {
          ageTableData.map((item, index) => {
            return (
              <tr key={index}>
                <td>
                  <div className='row-flex'>
                    <Select value={item.lower_operator} onChange={(e) => onChangeHandler(e, 'low', 'select', index)}>
                      <Option value='gt'>gt</Option>
                      <Option value='gte'>gte</Option>
                    </Select>&nbsp;
                    <InputNumber value={item.lower_operand} onChange={(e) => onChangeHandler(e, 'low', 'input', index)} />
                  </div>
                </td>
                <td>
                  <div className='row-flex'>
                    <Select value={item.upper_operator} onChange={(e) => onChangeHandler(e, 'high', 'select', index)}>
                      <Option value='lt'>lt</Option>
                      <Option value='lte'>lte</Option>
                    </Select>&nbsp;
                    <InputNumber value={item.upper_operand} onChange={(e) => onChangeHandler(e, 'high', 'input', index)} />
                  </div>
                </td>
                <td>
                  <InputNumber
                    required
                    className='full-width mapped-derived'
                    formatter={value => `${value}%`}
                    parser={value => value.replace('%', '')}
                    value={get(item, 'value.premium_logic.value')}
                    onChange={(e) => derivedPercentageHandler(e, index)}
                  />
                </td>
                <td>
                  <div className='iconDiv'>
                    <Icon
                      className='dynamic-add-button button-size'
                      type='plus-circle'
                      theme='filled'
                      onClick={() => addButtonHandler()}
                    />
                    {
                      ageTableData.length > 1 &&
                        <Icon
                          className='dynamic-delete-button button-size'
                          type='minus-circle'
                          theme='filled'
                          onClick={() => deleteButtonHandler(index)}
                        />
                    }
                  </div>
                </td>
              </tr>
            )
          })
        }
      </tbody>
    </table>
  )
}
