/* eslint-disable react-hooks/exhaustive-deps */
import { Select, InputNumber, Icon } from 'antd'
import { useContext, useEffect } from 'react'
import { get } from 'lodash'
import { store } from '../../../../store'
const { Option } = Select

export function RangedDerived ({ initialData = [], initRootAttributePath, fieldKey, sectionView }) {
  const { state, dispatch } = useContext(store)
  const rangedProductAttributeId = get(state, `${initRootAttributePath}.ranged.product_attribute_id`, get(state, `${fieldKey}[0].product_attribute_id`))
  const derivedProductAttributeId = get(state, `${initRootAttributePath}.derived.product_attribute_id`, get(state, `${fieldKey}[0].value.premium_logic.product_attribute_id`))

  useEffect(() => {
    const updatedData = initialData.map(data => ({
      ...data,
      product_attribute_id: rangedProductAttributeId
    }))

    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: updatedData
      }
    })
  }, [rangedProductAttributeId])

  useEffect(() => {
    const updatedData = initialData.map(data => ({
      ...data,
      value: {
        ...data?.value,
        premium_logic: {
          ...data?.value?.premium_logic,
          product_attribute_id: derivedProductAttributeId
        }
      }
    }))

    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: updatedData
      }
    })
  }, [derivedProductAttributeId])

  const onChangeHandler = (e, type, fieldType, id) => {
    // let payload = []
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}[${id}].product_attribute_id`,
        data: rangedProductAttributeId
      }
    })
    switch (type) {
      case 'low': {
        if (fieldType === 'select') {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}[${id}].lower_operator`,
              data: e
            }
          })
        } else {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}[${id}].lower_operand`,
              data: Number(e)
            }
          })
        }
        break
      }
      case 'high': {
        if (fieldType === 'select') {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}[${id}].upper_operator`,
              data: e
            }
          })
        } else {
          dispatch({
            type: 'update-store',
            payload: {
              view: sectionView,
              key: `${fieldKey}[${id}].upper_operand`,
              data: Number(e)
            }
          })
        }
        break
      }
      default: return ''
    }
  }

  const premiumHandler = (e, id) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}[${id}].value`,
        data: {
          premium_logic: {
            value: e,
            product_attribute_id: derivedProductAttributeId
          },
          premium_type: 'derived'
        }
      }
    })
  }

  const addButtonHandler = () => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: [...initialData, {}]
      }
    })
  }

  const deleteButtonHandler = (id) => {
    // const payload = buttonHandlerFunction('delte', state, id, sectionView)
    const filterData = initialData.filter((_item, index) => index !== id)
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: filterData
      }
    })
  }
  return (
    <table>
      <thead>
        <tr>
          <th>Range Lower Value</th>
          <th>Range Higher Value</th>
          <th>Premium</th>
          <th />
        </tr>
      </thead>
      <tbody>
        {
          initialData.map((item, index) => {
            return (
              <tr key={index}>
                <td>
                  <div className='row-flex'>
                    <Select value={item.lower_operator} onChange={(e) => onChangeHandler(e, 'low', 'select', index)}>
                      <Option value='gt'>gt</Option>
                      <Option value='gte'>gte</Option>
                    </Select>&nbsp;
                    <InputNumber value={item.lower_operand} onChange={(e) => onChangeHandler(e, 'low', 'input', index)} />
                  </div>
                </td>
                <td>
                  <div className='row-flex'>
                    <Select value={item.upper_operator} onChange={(e) => onChangeHandler(e, 'high', 'select', index)}>
                      <Option value='lt'>lt</Option>
                      <Option value='lte'>lte</Option>
                    </Select>&nbsp;
                    <InputNumber value={item.upper_operand} onChange={(e) => onChangeHandler(e, 'high', 'input', index)} />
                  </div>
                </td>
                <td>
                  <InputNumber
                    required
                    className='full-width mapped-derived'
                    formatter={value => `${value}%`}
                    parser={value => value.replace('%', '')}
                    // value={item.value.value}
                    value={get(item, 'value.premium_logic.value')}
                    onChange={(e) => premiumHandler(e, index)}
                  />
                </td>
                <td>
                  <div className='iconDiv'>
                    <Icon
                      className='dynamic-add-button button-size'
                      type='plus-circle'
                      theme='filled'
                      onClick={() => addButtonHandler()}
                    />
                    {
                      initialData.length > 1 &&
                        <Icon
                          className='dynamic-delete-button button-size'
                          type='minus-circle'
                          theme='filled'
                          onClick={() => deleteButtonHandler(index)}
                        />
                    }
                  </div>
                </td>
              </tr>
            )
          })
        }
      </tbody>
    </table>
  )
}
