/* eslint-disable react-hooks/exhaustive-deps */
import { useState, useContext, useEffect } from 'react'
import { Row, Col, Select } from 'antd'
import AttributeSection from './attributeSection'
import { store } from '../../store'
import TableSection from './tableSection'
import { get } from 'lodash'

const { Option } = Select

const defaultPremiumLogic1 = [{
  code: 'mapped', name: 'Mapped'
}, {
  code: 'derived', name: 'Derived'
}, {
  code: 'ranged', name: 'Ranged'
}, {
  code: 'age', name: 'Age'
}]

export default function CombinedPremium ({ parentKey, sectionView, initialFormData = {}, attributesData }) {
  const { state, dispatch } = useContext(store)
  // const [premiumType1, setPremiumType1] = useState('')
  // const [premiumType2, setPremiumType2] = useState('')
  const [premiumLogic1Data, setPremiumLogic1Data] = useState(defaultPremiumLogic1)
  const [premiumLogic2Data, setPremiumLogic2Data] = useState([])
  const premiumTypeKey = sectionView === 'endorsement' ? 'endorsement_combined_type' : 'combined_type'
  // const premiumStoreType = sectionView === 'endorsement' ? 'endorsement_type' : 'type'
  const premiumType = get(state, premiumTypeKey, '')

  const [premiumType1, premiumType2] = premiumType.includes('_') ? premiumType.split('_') : ''

  const initAttributePath = parentKey || (sectionView === 'endorsement' ? 'endorsement_new_premium_logic.premium_logic' : 'new_premium_logic.premium_logic')
  const initRootAttributePath = parentKey || (sectionView === 'endorsement' ? 'endorsement_premium_store' : 'new_premium_logic_store')
  const fieldKey = parentKey || initAttributePath

  const handlepremiumType1 = (e) => {
    // setPremiumType1(e)
    dispatch({
      type: 'update-type',
      payload: {
        view: sectionView,
        state: 'combined',
        value: `${e}_${undefined}`
      }
    })
  }

  useEffect(() => {
    switch (premiumType1) {
      case 'mapped':
        setPremiumLogic2Data([
          { code: 'derived', name: 'Derived' }
        ])
        break
      case 'ranged':
        setPremiumLogic2Data([
          { code: 'derived', name: 'Derived' },
          { code: 'mapped', name: 'Mapped' }
        ])
        break
      case 'age':
        setPremiumLogic2Data([
          { code: 'derived', name: 'Derived' },
          { code: 'mapped', name: 'Mapped' }
        ])
        break
      default:
        setPremiumLogic2Data([])
        break
    }
  }, [premiumType1])

  useEffect(() => {
    switch (premiumType2) {
      case 'derived':
        setPremiumLogic1Data([
          { code: 'mapped', name: 'Mapped' },
          { code: 'ranged', name: 'Ranged' },
          { code: 'age', name: 'Age' }
        ])
        break
      case 'mapped':
        setPremiumLogic1Data([
          { code: 'ranged', name: 'Ranged' },
          { code: 'age', name: 'Age' }
        ])
        break
      default:
        setPremiumLogic1Data([{
          code: 'mapped', name: 'Mapped'
        }, {
          code: 'derived', name: 'Derived'
        }, {
          code: 'ranged', name: 'Ranged'
        }, {
          code: 'age', name: 'Age'
        }])
        break
    }
  }, [premiumType2])

  const handlepremiumType2 = (e) => {
    // setPremiumType2(e)
    dispatch({
      type: 'update-type',
      payload: {
        view: sectionView,
        state: 'combined',
        value: `${premiumType1}_${e}`
      }
    })

    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: undefined
      }
    })
  }

  return (
    <>
      <Row type='flex' gutter={100}>
        <Col>
          <p> 1st premium logic</p>
        </Col>
        <Col>
          <Select allowClear value={premiumType1} placeholder='select policy data' onChange={handlepremiumType1}>
            {premiumLogic1Data.map((item, index) => <Option key={index} value={item.code}>{item.name}</Option>)}
          </Select>
        </Col>
      </Row>
      <Row type='flex' gutter={100}>
        <Col>
          <p> 2nd premium logic</p>
        </Col>
        <Col>
          <Select
            allowClear
            value={premiumType2}
            placeholder='select policy data'
            onChange={handlepremiumType2}
          >
            {premiumLogic2Data.map((item, index) => <Option key={index} value={item.code}>{item.name}</Option>)}
          </Select>
        </Col>
      </Row>
      {
        premiumType1 && premiumType2 &&
          <AttributeSection
            sectionView={sectionView}
            fieldKey={fieldKey}
            initRootAttributePath={initRootAttributePath}
            type={sectionView === 'endorsement' ? `endorsement_${premiumType1}_${premiumType2}` : `${premiumType1}_${premiumType2}`}
            premiumType1={premiumType1}
            premiumType2={premiumType2}
            attributesData={attributesData}
          />
      }
      {
        (premiumType1 && premiumType2) &&
          <TableSection
            sectionView={sectionView}
            fieldKey={fieldKey}
            initRootAttributePath={initRootAttributePath}
            type={sectionView === 'endorsement' ? `endorsement_${premiumType1}_${premiumType2}` : `${premiumType1}_${premiumType2}`}
          />
      }
    </>
  )
}
