import { useContext } from 'react'
import styled from 'styled-components'
import { TreeSelect, Select } from 'antd'
import { get } from 'lodash'

import { store } from '../../store'
import { childNode } from '../../../../../../../../components/formItem'

const { Option } = Select

const DurationWrapper = styled.div`
  .duration {
    &__container {

    }
    &__duration-container {
      display: flex;
      gap: 8px;
    }
    &__parameter-container {
      display: flex;
      gap: 8px;
    }
  }
`

const RangedWrapper = styled.div`
  .ranged {
    &__container {
      display: flex;
      align-items: center;
    }
    &__container > * {
      margin-right: 5px;
    }
    &__duration-container {
      display: flex;
      gap: 8px;
    }
  }
`

export default function CalculationForm (props) {
  const { state, dispatch } = useContext(store)
  // TODO: Figure out why this and PremiumTypeComponent cannot be made into single component
  const {
    type,
    sectionView,
    parentKey,
    // fieldKey,
    // initialFormData,
    attributesData
  } = props

  switch (type) {
    case 'mapped':
    case 'ranged': {
      const onChangeHandler = (value) => {
        let values = get(state, parentKey, [])

        if (Array.isArray(values)) {
          if (!values.length) {
            values = [{ product_attribute_id: value }]
          } else {
            values = values.map(v => {
              v.product_attribute_id = value
              return v
            })
          }
        } else {
          values = [{ product_attribute_id: value }]
        }

        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: parentKey,
            data: values
          }
        })
      }
      return (
        <RangedWrapper>
          <div className='ranged__container'>
            <span>
              Parameter
            </span>
            <div>
              <TreeSelect
                value={get(state, `${parentKey}[0].product_attribute_id`)}
                placeholder='Select Attribute...'
                treeDefaultExpandAll
                onChange={onChangeHandler}
              >
                {
                  childNode(attributesData)
                }
              </TreeSelect>
            </div>
          </div>
        </RangedWrapper>
      )
    }
    case 'age': {
      const tableData = get(state, parentKey, {})
      const firstParameter = get(tableData, 'first_parameter', {})
      const secondParameter = get(tableData, 'second_parameter', {})
      const unit = get(tableData, 'unit')
      const treeSelectInput1 = get(firstParameter, 'is_current_time', false) ? 'currentTime' : get(firstParameter, 'product_attribute_id')
      const treeSelectInput2 = get(secondParameter, 'is_current_time', false) ? 'currentTime' : get(secondParameter, 'product_attribute_id')
      const localAttributesData = [...attributesData]

      if (!localAttributesData.find(x => x.id === 'currentTime')) {
        // TODO: Move and change this, inefficient
        localAttributesData.push({
          attribute_type: '',
          id: 'currentTime',
          name: 'Current Time',
          nested: []
        })
      }

      const onChangeParameter = (value, key) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}.${key}`,
            data: {
              is_current_time: value === 'currentTime',
              product_attribute_id: value !== 'currentTime' ? value : null
            }
          }
        })
      }

      const onChangeUnit = (value) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}.unit`,
            data: value
          }
        })
      }

      return (
        <DurationWrapper>
          <div className='duration__container'>
            <section className='duration__duration-container'>
              <div>
                Age =
              </div>
              <div className='duration__parameter-container'>
                <TreeSelect
                  value={treeSelectInput1}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={e => onChangeParameter(e, 'first_parameter')}
                >
                  {
                    childNode(localAttributesData)
                  }
                </TreeSelect>
                <span>
                  -
                </span>
                <TreeSelect
                  value={treeSelectInput2}
                  placeholder='Select Attribute...'
                  treeDefaultExpandAll
                  onChange={e => onChangeParameter(e, 'second_parameter')}
                >
                  {
                    childNode(localAttributesData)
                  }
                </TreeSelect>
              </div>
            </section>
            <section>
              <span>
                Calculation Unit
              </span>
              <Select
                style={{ width: 200 }}
                value={unit}
                onChange={e => onChangeUnit(e)}
              >
                <Option key='year' value='year'>Year</Option>
                <Option key='month' value='month'>Month</Option>
                <Option key='day' value='day'>Day</Option>
              </Select>
            </section>
          </div>
        </DurationWrapper>
      )
    }
    default:
      return (
        <div>
          Unconfigured type: {type}
        </div>
      )
  }
}
