import { get } from 'lodash'
import { TreeSelect, Icon, Input, Select } from 'antd'
import styled from 'styled-components'

import { FixedComponent } from '../normalPremium/FixedComponent'
import { DerivedComponent } from '../normalPremium/DerivedComponent'

import { childNode } from '../../../../../../../../components/formItem'

import { store } from '../../store'

const { Option } = Select

