export default function FormItems (formData) {
  // TODO: Figure out why this and PremiumTypeComponent cannot be made into single component
  const {
    type,
    sectionView,
    parentKey,
    initialFormData,
    attributesData
  } = formData

  const { state, dispatch } = useContext(store)

  switch (type) {
    case 'fixed':
      return (
        <FixedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
        />
      )
    case 'derived':
      return (
        <DerivedComponent
          parentKey={parentKey}
          sectionView={sectionView}
          initialFormData={initialFormData}
          attributesData={attributesData}
        />
      )
    case 'mapped': {
      const tableData = get(state, parentKey, [])

      const onChangeHandler = (value) => {
        let values = tableData

        if (Array.isArray(values)) {
          if (!values.length) {
            values = [{ product_attribute_id: value }]
          } else {
            values = values.map(v => {
              v.product_attribute_id = value
              return v
            })
          }
        } else {
          values = [{ product_attribute_id: value }]
        }

        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: parentKey,
            data: values
          }
        })
      }

      const onChangeOperand = (value, idx) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}[${idx}].operand`,
            data: value
          }
        })
      }

      const add = () => {
        // const currValues = get(state, `${parentKey}`, [])
        const newValues = [...tableData, {}]
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}`,
            data: newValues
          }
        })
      }

      const remove = (targetIndex) => {
        const newValues = tableData.filter((_, index) => index !== targetIndex)
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}`,
            data: newValues
          }
        })
      }

      return (
        <MappedWrapper>
          <div>
            <span>
              Parameter:
            </span>
            <div>
              <TreeSelect
                value={get(state, `${parentKey}[0].product_attribute_id`)}
                placeholder='Select Attribute...'
                treeDefaultExpandAll
                onChange={e => onChangeHandler(e)}
              >
                {
                  childNode(attributesData)
                }
              </TreeSelect>
            </div>

            <section className='mapped__value-list'>
              {get(state, `${parentKey}[0].product_attribute_id`) && (
                <div className='mapped__value-item'>
                  {
                    tableData.map((fieldObj, index) => (
                      <div key={index} className='mapped__value-container'>
                        <div className='mapped__value-header'>
                          <span>Map Value</span>
                          {
                            tableData.length > 1 &&
                              <Icon
                                className='dynamic-delete-button button-size'
                                type='minus-circle'
                                theme='filled'
                                onClick={() => remove(index)}
                              />
                          }
                        </div>
                        <Input
                          style={{ width: '100%' }}
                          value={fieldObj.operand}
                          onChange={e => onChangeOperand(e.target.value, index)}
                        />
                      </div>
                    ))
                  }
                </div>
              )}
              <div className='mapped__add-container'>
                <Icon
                  type='plus-circle'
                  theme='filled'
                  onClick={add}
                />
              </div>
            </section>
          </div>
        </MappedWrapper>
      )
    }
    case 'ranged': {
      const tableData = get(state, parentKey, [])
      const onChangeHandler = (value, path) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: path,
            data: value
          }
        })
      }

      const onChangeAttribute = (value) => {
        let values = tableData

        if (Array.isArray(values)) {
          if (!values.length) {
            values = [{ product_attribute_id: value }]
          } else {
            values = values.map(v => {
              v.product_attribute_id = value
              return v
            })
          }
        } else {
          values = [{ product_attribute_id: value }]
        }

        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: parentKey,
            data: values
          }
        })
      }

      const add = () => {
        const currValues = get(state, parentKey, [])
        let values = []
        if (Array.isArray(currValues)) {
          values = [...currValues, {}]
        } else {
          values = [{}]
        }
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: parentKey,
            data: values
          }
        })
      }

      const remove = (targetIndex) => {
        const currValues = get(state, parentKey, [])
        const newValues = currValues.filter((_, index) => index !== targetIndex)
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: parentKey,
            data: newValues
          }
        })
      }

      return (
        <RangedWrapper>
          <section>
            <span>
              Parameter
            </span>
            <div>
              <TreeSelect
                value={get(state, `${parentKey}[0].product_attribute_id`)}
                placeholder='Select Attribute...'
                treeDefaultExpandAll
                onChange={e => onChangeAttribute(e)}
              >
                {
                  childNode(attributesData)
                }
              </TreeSelect>
            </div>
          </section>

          <section className='ranged__mapped-list'>
            {Array.isArray(tableData) && tableData.map((item, index) => (
              <div key={index} className='ranged__value-item'>
                {
                  tableData.length > 1 &&
                    <Icon
                      className='dynamic-delete-button button-size'
                      type='minus-circle'
                      theme='filled'
                      onClick={() => remove(index)}
                    />
                }
                <div className='ranged__item'>
                  <div className='ranged__addon-container'>
                    <div
                      className={'ranged__addon' + (item.upper_operator === 'gt' ? ' ranged__addon--active' : '')}
                      onClick={() => onChangeHandler('gt', `${parentKey}[${index}].upper_operator`)}
                    >
                      gt
                    </div>
                    <div
                      className={'ranged__addon' + (get(state, `${parentKey}[${index}].upper_operator`) === 'gte' ? ' ranged__addon--active' : '')}
                      onClick={() => onChangeHandler('gte', `${parentKey}[${index}].upper_operator`)}
                    >
                      gte
                    </div>
                  </div>
                  <Input
                    type='number'
                    style={{ width: '100%' }}
                    value={get(state, `${parentKey}[${index}].upper_operand`)}
                    onChange={e => onChangeHandler(Number(e?.target?.value), `${parentKey}[${index}].upper_operand`)}
                  />
                </div>
                <div>
                  <div className='ranged__item'>
                    <div className='ranged__addon-container'>
                      <div
                        className={'ranged__addon' + (get(state, `${parentKey}[${index}].lower_operator`) === 'lt' ? ' ranged__addon--active' : '')}
                        onClick={() => onChangeHandler('lt', `${parentKey}[${index}].lower_operator`)}
                      >
                        lt
                      </div>
                      <div
                        className={'ranged__addon' + (get(state, `${parentKey}[${index}].lower_operator`) === 'lte' ? ' ranged__addon--active' : '')}
                        onClick={() => onChangeHandler('lte', `${parentKey}[${index}].lower_operator`)}
                      >
                        lte
                      </div>
                    </div>
                    <Input
                      type='number'
                      style={{ width: '100%' }}
                      value={get(state, `${parentKey}[${index}].lower_operand`)}
                      onChange={e => onChangeHandler(Number(e?.target?.value), `${parentKey}[${index}].lower_operand`)}
                    />
                  </div>
                </div>
              </div>
            ))}

            <div className='ranged__add-container'>
              <Icon
                type='plus-circle'
                theme='filled'
                onClick={add}
              />
            </div>
          </section>
        </RangedWrapper>
      )
    }
    case 'age': {
      const tableData = get(state, parentKey, {})
      const firstParameter = get(tableData, 'first_parameter', {})
      const secondParameter = get(tableData, 'second_parameter', {})
      const unit = get(tableData, 'unit')
      const tableValues = get(tableData, 'values', [])
      const treeSelectInput1 = get(firstParameter, 'is_current_time', false) ? 'currentTime' : get(firstParameter, 'product_attribute_id')
      const treeSelectInput2 = get(secondParameter, 'is_current_time', false) ? 'currentTime' : get(secondParameter, 'product_attribute_id')
      const localAttributesData = [...attributesData]

      if (!localAttributesData.find(x => x.id === 'currentTime')) {
        // TODO: Move and change this, inefficient
        localAttributesData.push({
          attribute_type: '',
          id: 'currentTime',
          name: 'Current Time',
          nested: []
        })
      }

      const onChangeParameter = (value, key) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}.${key}`,
            data: {
              is_current_time: value === 'currentTime',
              product_attribute_id: value !== 'currentTime' ? value : null
            }
          }
        })
      }

      const onChangeUnit = (value) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}.unit`,
            data: value
          }
        })
      }

      const onChangeHandler = (value, key) => {
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: key,
            data: value
          }
        })
      }

      const add = () => {
        const currValues = tableValues
        const newValues = [...currValues, {}]
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}.values`,
            data: newValues
          }
        })
      }

      const remove = (targetIndex) => {
        const currValues = tableValues
        const newValues = currValues.filter((_, index) => index !== targetIndex)
        dispatch({
          type: 'update-store',
          payload: {
            view: sectionView,
            key: `${parentKey}.values`,
            data: newValues
          }
        })
      }

      return (
        <DurationWrapper>
          <section className='duration__container'>
            <div>
              Age =
            </div>
            <div className='duration__parameter-container'>
              <TreeSelect
                value={treeSelectInput1}
                placeholder='Select Attribute...'
                treeDefaultExpandAll
                onChange={e => onChangeParameter(e, 'first_parameter')}
              >
                {
                  childNode(localAttributesData)
                }
              </TreeSelect>
              <span>
                -
              </span>
              <TreeSelect
                value={treeSelectInput2}
                placeholder='Select Attribute...'
                treeDefaultExpandAll
                onChange={e => onChangeParameter(e, 'second_parameter')}
              >
                {
                  childNode(localAttributesData)
                }
              </TreeSelect>
            </div>
          </section>
          <section>
            <span>
              Calculation Unit
            </span>
            <div>
              <Select
                style={{ width: 200 }}
                value={unit}
                onChange={e => onChangeUnit(e)}
              >
                <Option key='year' value='year'>Year</Option>
                <Option key='month' value='month'>Month</Option>
                <Option key='day' value='day'>Day</Option>
              </Select>
            </div>
          </section>

          <section className='duration__mapped-list'>
            {Array.isArray(tableValues) && tableValues.map((_, index) => (
              <div key={index} className='duration__value-item'>
                {
                  tableValues.length > 1 &&
                    <Icon
                      className='dynamic-delete-button button-size'
                      type='minus-circle'
                      theme='filled'
                      onClick={() => remove(index)}
                    />
                }
                <div className='duration__item'>
                  <div className='duration__addon-container'>
                    <div
                      className={'duration__addon' + (get(state, `${parentKey}.values[${index}].upper_operator`) === 'gt' ? ' duration__addon--active' : '')}
                      onClick={() => onChangeHandler('gt', `${parentKey}.values[${index}].upper_operator`)}
                    >
                      gt
                    </div>
                    <div
                      className={'duration__addon' + (get(state, `${parentKey}.values[${index}].upper_operator`) === 'gte' ? ' duration__addon--active' : '')}
                      onClick={() => onChangeHandler('gte', `${parentKey}.values[${index}].upper_operator`)}
                    >
                      gte
                    </div>
                  </div>
                  <Input
                    type='number'
                    style={{ width: '100%' }}
                    value={get(state, `${parentKey}.values[${index}].upper_operand`)}
                    onChange={e => onChangeHandler(Number(e.target.value), `${parentKey}.values[${index}].upper_operand`)}
                  />
                </div>
                <div>
                  <div className='duration__item'>
                    <div className='duration__addon-container'>
                      <div
                        className={'duration__addon' + (get(state, `${parentKey}.values[${index}].lower_operator`) === 'lt' ? ' duration__addon--active' : '')}
                        onClick={() => onChangeHandler('lt', `${parentKey}.values[${index}].lower_operator`)}
                      >
                        lt
                      </div>
                      <div
                        className={'duration__addon' + (get(state, `${parentKey}.values[${index}].lower_operator`) === 'lte' ? ' duration__addon--active' : '')}
                        onClick={() => onChangeHandler('lte', `${parentKey}.values[${index}].lower_operator`)}
                      >
                        lte
                      </div>
                    </div>
                    <Input
                      type='number'
                      style={{ width: '100%' }}
                      value={get(state, `${parentKey}.values[${index}].lower_operand`)}
                      onChange={e => onChangeHandler(Number(e?.target?.value), `${parentKey}.values[${index}].lower_operand`)}
                    />
                  </div>
                </div>
              </div>
            ))}

            <div className='duration__add-container'>
              <Icon
                type='plus-circle'
                theme='filled'
                onClick={add}
              />
            </div>
          </section>
        </DurationWrapper>
      )
    }
    default:
      return (
        <div>
          Unconfigured type: {type}
        </div>
      )
  }
}
