import { useState, useContext } from 'react'

import { SummationPremiumContainer } from './index.style'
import { store } from '../../store'
import { get } from 'lodash'
import { Select, Input, Icon, Checkbox, Row, Col } from 'antd'
import { getFormItems } from './getFormItems'

const { Option } = Select

export default function MultipliedPremium ({ attributesData, initialFormData = {}, sectionView, parentKey, getFieldDecorator }) {
  const { state, dispatch } = useContext(store)
  const initAttributePath = sectionView === 'endorsement' ? 'endorsement_new_premium_logic.premium_logic' : 'new_premium_logic.premium_logic'
  const fieldKey = parentKey || initAttributePath
  const [inputDisable, setInputDisable] = useState([])

  const values = get(state, fieldKey, [])

  const add = () => {
    const nextNumber = values.length
    setInputDisable(oldArray => [...oldArray, true])
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}[${nextNumber}]`,
        data: {}
      }
    })
  }

  const remove = k => {
    const currArr = [...values]
    currArr.splice(k, 1)

    const curInput = [...inputDisable]
    curInput.splice(k, 1)

    dispatchInit(currArr)
    setInputDisable(curInput)
  }

  const dispatchInit = (value) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: fieldKey,
        data: value
      }
    })
  }

  const handleChangeAttributeType = (e, idx) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}[${idx}].premium_logic.premium_type`,
        data: e
      }
    })
  }

  const handleChangeIsNegative = (e, idx) => {
    dispatch({
      type: 'update-store',
      payload: {
        view: sectionView,
        key: `${fieldKey}[${idx}].is_negative_value`,
        data: e.target.checked
      }
    })
  }

  const handleEyeBtn = (idx) => {
    const currArr = [...inputDisable]
    currArr[idx] = !currArr[idx]
    setInputDisable(currArr)
  }

  return (
    <SummationPremiumContainer>
      <p>This logic will sum the result of each premium logic added below</p>
      <section className='summation-premium__item-list'>
        {values.map((_, idx) => (
          <Row key={idx} className='summation-premium__item'>
            <Col span={6}>
              <Row>
                <Checkbox
                  style={{ marginTop: 20 }}
                  checked={get(values, `[${idx}].is_negative_value`)}
                  onChange={(e) => handleChangeIsNegative(e, idx)}
                >
                  Is Negative Value
                </Checkbox>
              </Row>
            </Col>
            <Col span={16}>
              <div className='input-wrapper'>
                <Select
                  style={{ width: 200 }}
                  value={get(values, `[${idx}].premium_logic.premium_type`)}
                  onChange={e => handleChangeAttributeType(e, idx)}
                >
                  <Option key='fixed' value='fixed'>Fixed</Option>
                  <Option key='derived' value='derived'>Derived</Option>
                  <Option key='mapped' value='mapped'>Mapped</Option>
                  <Option key='ranged' value='ranged'>Ranged Based</Option>
                  <Option key='age' value='age'>Duration Based</Option>
                </Select>
                <div className='tag-wrapper'>
                  <label>Tag: {'  '}</label>

                  {
                    getFieldDecorator(`${fieldKey}[${idx}].premium_logic.tagging_key`, {
                      rules: [
                        {
                          required: true,
                          message: 'required'
                        }
                      ],
                      initialValue: get(values, `[${idx}].premium_logic.code`) || get(values, `[${idx}].premium_logic.premium_type`)
                    })(<Input disabled={inputDisable[idx]} className='tag-input' />)
                  }
                  <Icon type='eye' className='pointer' onClick={() => handleEyeBtn(idx)} />
                </div>
              </div>
              {
                getFormItems.call(this, {
                  parentKey: `${fieldKey}[${idx}].premium_logic.premium_logic`,
                  type: get(values, `[${idx}].premium_logic.premium_type`),
                  required: true,
                  attributesData,
                  initialFormData,
                  sectionView
                })
              }
              {
                values.length > 1
                  ? (
                    <Icon
                      className='dynamic-delete-button'
                      type='minus-circle-o'
                      onClick={() => remove(idx)}
                    />
                    )
                  : null
                }
            </Col>
          </Row>
        ))}
      </section>
      <Icon
        className='summation__row-add dynamic-add-button button-size'
        type='plus-circle'
        theme='filled'
        onClick={add}
      />
    </SummationPremiumContainer>
  )
}
